from collections import deque
class Solution:
    def zigzagLevelSum(self, root: Optional[TreeNode]) -> List[int]:
        if not root: return []
        levels, q = [], deque([root])
        while q:
            lev = list(q); q.clear()
            nxt = []
            for nd in lev:
                if nd.left: nxt.append(nd.left)
                if nd.right: nxt.append(nd.right)
            levels.append(lev)
            q = deque(nxt)
        ans = []
        for i, lev in enumerate(levels):
            order = lev if i % 2 == 0 else lev[::-1]
            s = 0
            for nd in order:
                if (i % 2 == 0 and nd.left is None) or (i % 2 == 1 and nd.right is None):
                    break
                s += nd.val
            ans.append(s)
        return ans

