class Solution {
public:
    vector<int> zigzagLevelSum(TreeNode* root) {
        if (!root) return {};
        vector<vector<TreeNode*>> levels;
        vector<TreeNode*> q{root};
        while (!q.empty()) {
            levels.push_back(q);
            vector<TreeNode*> nxt;
            for (auto* nd : q) {
                if (nd->left) nxt.push_back(nd->left);
                if (nd->right) nxt.push_back(nd->right);
            }
            q = move(nxt);
        }
        vector<int> ans;
        for (int i = 0; i < (int)levels.size(); i++) {
            auto& lev = levels[i];
            long s = 0;
            int m = lev.size();
            for (int t = 0; t < m; t++) {
                TreeNode* nd = (i % 2 == 0) ? lev[t] : lev[m - 1 - t];
                if ((i % 2 == 0 && !nd->left) || (i % 2 == 1 && !nd->right)) break;
                s += nd->val;
            }
            ans.push_back((int)s);
        }
        return ans;
    }
};

