class Solution {
    public List<Integer> zigzagLevelSum(TreeNode root) {
        List<Integer> ans = new ArrayList<>();
        if (root == null) return ans;
        List<List<TreeNode>> levels = new ArrayList<>();
        List<TreeNode> q = new ArrayList<>();
        q.add(root);
        while (!q.isEmpty()) {
            levels.add(q);
            List<TreeNode> nxt = new ArrayList<>();
            for (TreeNode nd : q) {
                if (nd.left != null) nxt.add(nd.left);
                if (nd.right != null) nxt.add(nd.right);
            }
            q = nxt;
        }
        for (int i = 0; i < levels.size(); i++) {
            List<TreeNode> lev = levels.get(i);
            int m = lev.size();
            long s = 0;
            for (int t = 0; t < m; t++) {
                TreeNode nd = (i % 2 == 0) ? lev.get(t) : lev.get(m - 1 - t);
                if ((i % 2 == 0 && nd.left == null) || (i % 2 == 1 && nd.right == null)) break;
                s += nd.val;
            }
            ans.add((int) s);
        }
        return ans;
    }
}

