var zigzagLevelSum = function(root) {
    if (!root) return [];
    const levels = [];
    let q = [root];
    while (q.length) {
        levels.push(q);
        const nxt = [];
        for (const nd of q) {
            if (nd.left) nxt.push(nd.left);
            if (nd.right) nxt.push(nd.right);
        }
        q = nxt;
    }
    const ans = [];
    for (let i = 0; i < levels.length; i++) {
        const lev = levels[i], m = lev.length;
        let s = 0;
        for (let t = 0; t < m; t++) {
            const nd = (i % 2 === 0) ? lev[t] : lev[m - 1 - t];
            if ((i % 2 === 0 && !nd.left) || (i % 2 === 1 && !nd.right)) break;
            s += nd.val;
        }
        ans.push(s);
    }
    return ans;
};
